import { Controller, Get, Post, Put, Delete, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '예산·회계 담당자';

function numberOf(value: unknown, label: string): string {
  if (value === undefined || value === null || String(value).trim() === '' || !Number.isFinite(Number(value))) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + '을(를) 숫자로 입력해 주세요.');
  }
  return String(value).trim();
}

function integerOf(value: unknown, label: string): string {
  const text = numberOf(value, label);
  if (!Number.isInteger(Number(text))) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + '은(는) 정수여야 합니다.');
  }
  return text;
}

function optionalIntegerOf(value: unknown, label: string): string | null {
  if (value === undefined || value === null || String(value).trim() === '') {
    return null;
  }
  return integerOf(value, label);
}

@Controller('api/v1')
export class FnSfr00604Controller {
  @Get('/account-carryovers')
  async listAccountCarryovers(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const query = checks.queryOf(req.query);
    const fiscalYear = integerOf(query['fiscalYear'], '회계연도');
    const pageNo = Math.max(0, parseInt(String(query['page'] ?? '0'), 10) || 0);
    const size = Math.min(200, Math.max(1, parseInt(String(query['size'] ?? '20'), 10) || 20));
    return transaction(async (db) => {
      const totals = await db.query(
        `SELECT COUNT(*) AS "total" FROM account_carryover WHERE fiscal_year = CAST(:fiscalYear AS integer)`,
        { fiscalYear },
      );
      const items = await db.query(
        `SELECT account_carryover_id AS "accountCarryoverId",
                fiscal_year AS "fiscalYear",
                account_subject_id AS "accountSubjectId",
                partner_id AS "partnerId",
                carryover_amount AS "carryoverAmount",
                closing_status AS "closingStatus"
           FROM account_carryover
          WHERE fiscal_year = CAST(:fiscalYear AS integer)
          ORDER BY account_carryover_id
          LIMIT :size OFFSET :offset`,
        { fiscalYear, size, offset: pageNo * size },
      );
      return { items, page: pageNo, size, total: Number(totals[0]['total']) };
    });
  }

  @Post('/account-carryovers')
  @HttpCode(200)
  async createAccountCarryover(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const fiscalYear = integerOf(data['fiscalYear'], '회계연도');
    const accountSubjectId = integerOf(data['accountSubjectId'], '계정과목');
    const partnerId = optionalIntegerOf(data['partnerId'], '거래처');
    const carryoverAmount = numberOf(data['carryoverAmount'], '이월 금액');
    return transaction(async (db) => {
      const subjects = await db.query(
        `SELECT account_subject_id FROM account_subject WHERE account_subject_id = CAST(:id AS bigint)`,
        { id: accountSubjectId },
      );
      if (subjects.length === 0) {
        throw new ApiError(404, 'ACCOUNT_SUBJECT_NOT_FOUND', '등록되지 않은 계정과목입니다.');
      }
      if (partnerId !== null) {
        const partners = await db.query(
          `SELECT partner_id FROM partner WHERE partner_id = CAST(:id AS bigint)`,
          { id: partnerId },
        );
        if (partners.length === 0) {
          throw new ApiError(404, 'PARTNER_NOT_FOUND', '등록되지 않은 거래처입니다.');
        }
      }
      const rows = await db.query(
        `INSERT INTO account_carryover
           (fiscal_year, account_subject_id, partner_id, carryover_amount, closing_status, created_at, updated_at)
         VALUES
           (CAST(:fiscalYear AS integer), CAST(:accountSubjectId AS bigint), CAST(:partnerId AS bigint),
            CAST(:carryoverAmount AS numeric), '미마감', now(), now())
         RETURNING account_carryover_id AS "accountCarryoverId"`,
        { fiscalYear, accountSubjectId, partnerId, carryoverAmount },
      );
      return rows[0];
    });
  }

  @Put('/account-carryovers/:accountCarryoverId')
  async updateAccountCarryover(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = integerOf(req.params['accountCarryoverId'], '계정별 초기이월 ID');
    const data = checks.inputOf(req.body);
    const accountSubjectId = integerOf(data['accountSubjectId'], '계정과목');
    const partnerId = optionalIntegerOf(data['partnerId'], '거래처');
    const carryoverAmount = numberOf(data['carryoverAmount'], '이월 금액');
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT closing_status AS "closingStatus" FROM account_carryover WHERE account_carryover_id = CAST(:id AS bigint)`,
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'ACCOUNT_CARRYOVER_NOT_FOUND', '대상 이월내역이 없습니다.');
      }
      if (found[0]['closingStatus'] === '마감') {
        throw new ApiError(409, 'ACCOUNT_CARRYOVER_CLOSED', '마감된 이월내역입니다. 마감을 취소한 뒤 수정해 주세요.');
      }
      const subjects = await db.query(
        `SELECT account_subject_id FROM account_subject WHERE account_subject_id = CAST(:subjectId AS bigint)`,
        { subjectId: accountSubjectId },
      );
      if (subjects.length === 0) {
        throw new ApiError(404, 'ACCOUNT_SUBJECT_NOT_FOUND', '등록되지 않은 계정과목입니다.');
      }
      if (partnerId !== null) {
        const partners = await db.query(
          `SELECT partner_id FROM partner WHERE partner_id = CAST(:partnerId AS bigint)`,
          { partnerId },
        );
        if (partners.length === 0) {
          throw new ApiError(404, 'PARTNER_NOT_FOUND', '등록되지 않은 거래처입니다.');
        }
      }
      await db.execute(
        `UPDATE account_carryover
            SET account_subject_id = CAST(:accountSubjectId AS bigint),
                partner_id = CAST(:partnerId AS bigint),
                carryover_amount = CAST(:carryoverAmount AS numeric),
                updated_at = now()
          WHERE account_carryover_id = CAST(:id AS bigint)`,
        { id, accountSubjectId, partnerId, carryoverAmount },
      );
      return { accountCarryoverId: Number(id) };
    });
  }

  @Delete('/account-carryovers/:accountCarryoverId')
  async deleteAccountCarryover(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = integerOf(req.params['accountCarryoverId'], '계정별 초기이월 ID');
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT closing_status AS "closingStatus" FROM account_carryover WHERE account_carryover_id = CAST(:id AS bigint)`,
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'ACCOUNT_CARRYOVER_NOT_FOUND', '대상 이월내역이 없습니다.');
      }
      if (found[0]['closingStatus'] === '마감') {
        throw new ApiError(409, 'ACCOUNT_CARRYOVER_CLOSED', '마감된 이월내역입니다. 마감을 취소한 뒤 삭제해 주세요.');
      }
      await db.execute(
        `DELETE FROM account_carryover WHERE account_carryover_id = CAST(:id AS bigint)`,
        { id },
      );
      return {};
    });
  }

  @Post('/account-carryovers/:accountCarryoverId/close')
  @HttpCode(200)
  async closeAccountCarryover(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = integerOf(req.params['accountCarryoverId'], '계정별 초기이월 ID');
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT closing_status AS "closingStatus" FROM account_carryover WHERE account_carryover_id = CAST(:id AS bigint)`,
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'ACCOUNT_CARRYOVER_NOT_FOUND', '대상 이월내역이 없습니다.');
      }
      if (found[0]['closingStatus'] !== '미마감') {
        throw new ApiError(409, 'ACCOUNT_CARRYOVER_ALREADY_CLOSED', '이미 마감된 이월내역입니다.');
      }
      await db.execute(
        `UPDATE account_carryover SET closing_status = '마감', updated_at = now() WHERE account_carryover_id = CAST(:id AS bigint)`,
        { id },
      );
      return { closingStatus: '마감' };
    });
  }

  @Post('/account-carryovers/:accountCarryoverId/cancel-close')
  @HttpCode(200)
  async cancelCloseAccountCarryover(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = integerOf(req.params['accountCarryoverId'], '계정별 초기이월 ID');
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT closing_status AS "closingStatus" FROM account_carryover WHERE account_carryover_id = CAST(:id AS bigint)`,
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'ACCOUNT_CARRYOVER_NOT_FOUND', '대상 이월내역이 없습니다.');
      }
      if (found[0]['closingStatus'] !== '마감') {
        throw new ApiError(409, 'ACCOUNT_CARRYOVER_NOT_CLOSED', '마감되지 않은 이월내역입니다.');
      }
      await db.execute(
        `UPDATE account_carryover SET closing_status = '미마감', updated_at = now() WHERE account_carryover_id = CAST(:id AS bigint)`,
        { id },
      );
      return { closingStatus: '미마감' };
    });
  }
}

