import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Form,
  Field,
  NumberInput,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

type Mode =
  | { kind: 'create' }
  | { kind: 'edit'; row: Row }
  | { kind: 'delete'; row: Row }
  | { kind: 'close'; row: Row }
  | { kind: 'cancel'; row: Row };

export default function FnSfr00604Page({ role, notify }: PageProps) {
  const [yearInput, setYearInput] = useState<number | string>(new Date().getFullYear());
  const [year, setYear] = useState<number | string>(new Date().getFullYear());
  const [pageNo, setPageNo] = useState(0);
  const [mode, setMode] = useState<Mode | null>(null);
  const [accountSubjectId, setAccountSubjectId] = useState<number | string>('');
  const [partnerId, setPartnerId] = useState<number | string>('');
  const [amount, setAmount] = useState<number | string>('');

  const { data, error, reload } = useData<Page>(
    () => call<Page>('GET', '/account-carryovers', role, undefined, { fiscalYear: year, page: pageNo, size: 20 }),
    [year, pageNo, role],
  );

  function open(next: Mode) {
    if (next.kind === 'edit') {
      setAccountSubjectId(next.row['accountSubjectId'] as number);
      setPartnerId((next.row['partnerId'] as number | null) ?? '');
      setAmount(next.row['carryoverAmount'] as number);
    } else {
      setAccountSubjectId('');
      setPartnerId('');
      setAmount('');
    }
    setMode(next);
  }

  async function done(message: string) {
    setMode(null);
    notify(message);
    reload();
  }

  function search() {
    if (yearInput === '' || !Number.isInteger(Number(yearInput))) {
      notify('회계연도를 숫자로 입력해 주세요.');
      return;
    }
    setPageNo(0);
    setYear(yearInput);
  }

  function rowActions(row: Row) {
    const id = row['accountCarryoverId'];
    if (row['closingStatus'] === '미마감') {
      return (
        <span>
          <button className="ghost" onClick={(e) => { e.stopPropagation(); open({ kind: 'edit', row }); }}>수정</button>
          <button className="ghost" onClick={(e) => { e.stopPropagation(); open({ kind: 'delete', row }); }}>삭제</button>
          <button className="ghost" onClick={(e) => { e.stopPropagation(); open({ kind: 'close', row }); }}>마감</button>
        </span>
      );
    }
    return (
      <span key={String(id)}>
        <button className="ghost" onClick={(e) => { e.stopPropagation(); open({ kind: 'cancel', row }); }}>마감 취소</button>
      </span>
    );
  }

  function renderDrawer() {
    if (!mode) {
      return null;
    }
    if (mode.kind === 'create' || mode.kind === 'edit') {
      const editing = mode.kind === 'edit';
      return (
        <Drawer title={editing ? '이월내역 수정' : '이월내역 등록'} onClose={() => setMode(null)}>
          <Form
            submit={editing ? '수정합니다' : '등록합니다'}
            onSubmit={async () => {
              if (accountSubjectId === '' || amount === '' || (!editing && (year === '' || yearInput === ''))) {
                throw new Error('계정과목과 이월 금액을 입력해 주세요.');
              }
              if (!editing) {
                await call('POST', '/account-carryovers', role, {
                  fiscalYear: year,
                  accountSubjectId,
                  partnerId: partnerId === '' ? null : partnerId,
                  carryoverAmount: amount,
                });
                await done('이월내역을 등록했습니다.');
              } else {
                await call('PUT', '/account-carryovers/' + String(mode.row['accountCarryoverId']), role, {
                  accountSubjectId,
                  partnerId: partnerId === '' ? null : partnerId,
                  carryoverAmount: amount,
                });
                await done('이월내역을 수정했습니다.');
              }
            }}
          >
            {!editing ? (
              <Field label="회계연도" hint="조회 중인 회계연도로 등록합니다.">
                <span>{String(year)}</span>
              </Field>
            ) : null}
            <Field label="계정과목" required>
              <LookupSelect table="account_subject" role={role} value={accountSubjectId} onChange={setAccountSubjectId} />
            </Field>
            <Field label="거래처">
              <LookupSelect table="partner" role={role} value={partnerId} onChange={setPartnerId} placeholder="선택 안 함" />
            </Field>
            <Field label="이월 금액" required>
              <NumberInput value={amount} onChange={setAmount} />
            </Field>
          </Form>
        </Drawer>
      );
    }
    const id = String(mode.row['accountCarryoverId']);
    if (mode.kind === 'delete') {
      return (
        <Drawer title="이월내역 삭제" onClose={() => setMode(null)}>
          <Form
            submit="삭제합니다"
            danger
            note="삭제한 이월내역은 되돌릴 수 없습니다."
            onSubmit={async () => {
              await call('DELETE', '/account-carryovers/' + id, role);
              await done('이월내역을 삭제했습니다.');
            }}
          />
        </Drawer>
      );
    }
    if (mode.kind === 'close') {
      return (
        <Drawer title="이월내역 마감" onClose={() => setMode(null)}>
          <Form
            submit="마감합니다"
            note="마감하면 마감을 취소하기 전에는 수정하거나 삭제할 수 없습니다."
            onSubmit={async () => {
              await call('POST', '/account-carryovers/' + id + '/close', role, {});
              await done('마감했습니다.');
            }}
          />
        </Drawer>
      );
    }
    return (
      <Drawer title="마감 취소" onClose={() => setMode(null)}>
        <Form
          submit="마감을 취소합니다"
          note="마감을 취소하면 이월내역을 다시 수정할 수 있습니다."
          onSubmit={async () => {
            await call('POST', '/account-carryovers/' + id + '/cancel-close', role, {});
            await done('마감을 취소했습니다.');
          }}
        />
      </Drawer>
    );
  }

  return (
    <div className="doc">
      <section className="box">
        <h2>계정별 초기이월</h2>
        <Filters
          onSearch={search}
          onReset={() => {
            const current = new Date().getFullYear();
            setYearInput(current);
            setYear(current);
            setPageNo(0);
          }}
        >
          <Field label="회계연도" required>
            <NumberInput value={yearInput} onChange={setYearInput} />
          </Field>
        </Filters>
        {error ? <ErrorText text={error} /> : null}
        <Band total={data?.total}>
          <button onClick={() => open({ kind: 'create' })}>이월내역 등록</button>
        </Band>
        <DataTable
          rows={data?.items ?? []}
          empty="아직 등록한 이월내역이 없습니다. 이월내역 등록 버튼으로 첫 내역을 등록해 주세요."
          columns={[
            { key: 'accountSubjectId', label: '계정과목', render: (r) => <RefName table="account_subject" role={role} value={r['accountSubjectId']} /> },
            { key: 'partnerId', label: '거래처', render: (r) => (r['partnerId'] ? <RefName table="partner" role={role} value={r['partnerId']} /> : <span>-</span>) },
            { key: 'carryoverAmount', label: '이월 금액', render: (r) => <Num value={r['carryoverAmount']} /> },
            { key: 'closingStatus', label: '마감 여부', render: (r) => <Badge value={r['closingStatus']} /> },
            { key: 'actions', label: '처리', render: (r) => rowActions(r) },
          ]}
        />
        <Pager page={data?.page ?? 0} size={data?.size ?? 20} total={data?.total ?? 0} onPage={setPageNo} />
      </section>
      {renderDrawer()}
    </div>
  );
}
